package main

import (
	"context"
	"encoding/json"
	"fmt"
	"log"
	"os"
	"sync"

	"github.com/jepsen-io/maelstrom/demo/go"
)

// JournalEntry represents an entry in a journal
type JournalEntry struct {
	Position int    `json:"position"`
	Entry    int    `json:"entry"`
}

// AppendRequest is the request to append to a journal
type AppendRequest struct {
	Type       string            `json:"type"`
	MessageID  int               `json:"msg_id"`
	Journal    string            `json:"journal"`
	Entry      int               `json:"entry"`
	Positions  map[string]int    `json:"positions,omitempty"`
	InReplyTo  int               `json:"in_reply_to,omitempty"`
}

// AppendResponse is the response to an append request
type AppendResponse struct {
	Type       string            `json:"type"`
	MessageID  int               `json:"msg_id"`
	Position   int               `json:"position,omitempty"`
	Entries    map[string][]JournalEntry `json:"entries,omitempty"`
	Positions  map[string]int    `json:"positions,omitempty"`
}

// BookmarkRequest is the request to set a bookmark
type BookmarkRequest struct {
	Type       string            `json:"type"`
	MessageID  int               `json:"msg_id"`
	Journal    string            `json:"journal,omitempty"`
	InReplyTo  int               `json:"in_reply_to,omitempty"`
}

// BookmarksRequest is the request to get bookmarks for specified journals
type BookmarksRequest struct {
	Type       string            `json:"type"`
	MessageID  int               `json:"msg_id"`
	Journals   []string          `json:"journals"`
	InReplyTo  int               `json:"in_reply_to,omitempty"`
}

// Journal represents our local state for a journal
type Journal struct {
	Entries []JournalEntry // In-memory buffer, sorted by position
}

func main() {
	ctx := context.Background()
	node := maelstrom.NewNode("node")

	// Create a lin-kv client for persistent storage
	lkv := maelstrom.NewLinKV(node)

	// In-memory journals (for fast local access)
	journals := make(map[string]*Journal)
	var journalsMu sync.Mutex

	// State tracking replication progress for append operations
	type PendingAppend struct {
		Journal string
		MessageID int
	}
	pendingAppends := make(map[PendingAppend]struct{})
	var pendingMutex sync.Mutex

	// Handler for init message
	node.Handle("init", func(ctx context.Context, msg json.RawMessage) maelstrom.Message {
		return maelstrom.Reply(ctx, nil, "ignored")
	})

	// Handle append requests
	node.Handle("append", func(ctx context.Context, req maelstrom.Request[AppendRequest]) maelstrom.Message {
		r := req.Body

		// Create entry key: journal:position (we'll assign positions sequentially)
		journalName := r.Journal

		// Get current max position for this journal from storage or local memory
		var maxPos int
		entryKey := fmt.Sprintf("journal:%s:pos", journalName)

		// Read the next available position from lin-kv (this persists across restarts)
		pos, err := lkv.ReadInt(ctx, entryKey)
		if err == nil {
			maxPos = pos
		} else {
			// No entry exists yet, or read failed - use 0
			maxPos = 0
		}

		// Assign new position (must be strictly greater than current max)
		newPos := maxPos + 1

		// Update the stored position
		if err := lkv.Write(ctx, entryKey, newPos); err != nil {
			log.Printf("Error writing position for journal %s: %v", journalName, err)
		}

		// Store entry in lin-kv with key: journal:journalName:position
		entryKey = fmt.Sprintf("journal:%s:%d", journalName, newPos)
		if err := lkv.Write(ctx, entryKey, r.Entry); err != nil {
			log.Printf("Error writing entry %d to journal %s: %v", newPos, journalName, err)
		}

		// Store in local memory for fast reads
		journalsMu.Lock()
		if journals[journalName] == nil {
			journals[journalName] = &Journal{Entries: []JournalEntry{}}
		}
		journals[journalName].Entries = append(journals[journalName].Entries, JournalEntry{
			Position: newPos,
			Entry:    r.Entry,
		})
		journalsMu.Unlock()

		response := &AppendResponse{
			Type:   "appended",
			MessageID: r.MessageID,
			Position: newPos,
		}
		return maelstrom.Reply(ctx, response)
	})

	// Handle fetch requests
	node.Handle("fetch", func(ctx context.Context, req maelstrom.Request[AppendRequest]) maelstrom.Message {
		r := req.Body

		// Read entries from lin-kv for each journal requested
		resultEntries := make(map[string][]JournalEntry)

		for journalName, startPos := range r.Positions {
			var entries []JournalEntry

			// First try to read directly from lin-kv for this position
			currentPos := startPos

			// Keep reading until we find something or go past what's stored
			for {
				entryKey := fmt.Sprintf("journal:%s:%d", journalName, currentPos)
				var entryVal int
				found, err := lkv.ReadInt(ctx, entryKey)
				if err != nil || !found {
					// Entry not found at this position or error - stop reading
					break
				}
				entryVal = found

				entries = append(entries, JournalEntry{
					Position: currentPos,
					Entry:    entryVal,
				})

				// Try to read the next position (position must strictly increase)
				nextKey := fmt.Sprintf("journal:%s:pos", journalName)
				currentPos, err = lkv.ReadInt(ctx, nextKey)
				if err != nil {
					break
				}
				currentPos++
			}

			resultEntries[journalName] = entries
		}

		response := &AppendResponse{
			Type:     "fetched",
			MessageID: r.MessageID,
			Entries:  resultEntries,
		}
		return maelstrom.Reply(ctx, response)
	})

	// Handle bookmark requests
	node.Handle("bookmark", func(ctx context.Context, req maelstrom.Request[BookmarkRequest]) maelstrom.Message {
		r := req.Body

		// Store bookmark position for this journal on this node
		key := fmt.Sprintf("bookmark:%s:%d", r.Journal, r.Position)
		if err := lkv.Write(ctx, key, true); err != nil {
			log.Printf("Error writing bookmark %s: %v", key, err)
		}

		response := &AppendResponse{
			Type:       "bookmarked",
			MessageID:  r.MessageID,
		}
		return maelstrom.Reply(ctx, response)
	})

	// Handle bookmarks requests (get multiple bookmarks)
	node.Handle("bookmarks", func(ctx context.Context, req maelstrom.Request[BookmarksRequest]) maelstrom.Message {
		r := req.Body

		resultPositions := make(map[string]int)

		for _, journalName := range r.Journals {
			key := fmt.Sprintf("bookmark:%s:max", journalName)
			pos, err := lkv.ReadInt(ctx, key)
			if err != nil || pos <= 0 {
				// Try reading from local memory instead
				journalsMu.Lock()
				journal := journals[journalName]
				if journal != nil && len(journal.Entries) > 0 {
					pos = journal.Entries[len(journal.Entries)-1].Position
				}
				journalsMu.Unlock()

				// Check if we have this bookmark on our storage
				bkKey := fmt.Sprintf("bookmark:%s", journalName)
				found, _ := lkv.ReadInt(ctx, bkKey)
				if found > 0 {
					resultPositions[journalName] = int(found)
				} else {
					// Read max position from storage
					maxKey := fmt.Sprintf("journal:%s:pos", journalName)
					pos, _ := lkv.ReadInt(ctx, maxKey)
					if pos > 0 {
						resultPositions[journalName] = int(pos) - 1
					}
				}
			} else {
				resultPositions[journalName] = int(pos) - 1
			}
		}

		response := &AppendResponse{
			Type:       "bookmarks_are",
			MessageID:  r.MessageID,
			Positions:  resultPositions,
		}
		return maelstrom.Reply(ctx, response)
	})

	node.Run(ctx)
}

