	node.Handle("bookmarks", func(ctx context.Context, req maelstrom.Request[BookmarksRequest]) maelstrom.Message {
		r := req.Body

		resultPositions := make(map[string]int)

		for _, journalName := range r.Journals {
			bkKey := fmt.Sprintf("bookmark:%s", journalName)
			pos, err := lkv.ReadInt(ctx, bkKey)
			if err != nil || pos <= 0 {
				pos = 0
			}
			resultPositions[journalName] = int(pos)
		}

		response := &AppendResponse{
			Type:       "bookmarks_are",
			MessageID:  r.MessageID,
			Positions:  resultPositions,
		}
		return maelstrom.Reply(ctx, response)
	})

	node.Run(ctx)
}

// readJournalForFetch reads entries from a journal starting at startPos
func readJournalForFetch(ctx context.Context, lkv *maelstrom.LinKVClient, journals map[string]*Journal, journalName string, startPos int) []JournalEntry {
	if journalName == "" {
		return nil
	}

	result := make([]JournalEntry, 0)

	// First check in-memory cache
	journalsMu.Lock()
	journal := journals[journalName]
	journalsMu.Unlock()

	if journal != nil && len(journal.Entries) > 0 {
		// Build a map of positions to entries for quick lookup
		entryMap := make(map[int]JournalEntry)
		for _, e := range journal.Entries {
			entryMap[e.Position] = e
		}

		// Check if startPos is valid (less than or equal to max position)
		var lastPos int
		if len(entryMap) > 0 {
			for pos, _ := range entryMap {
				lastPos = pos
			}
		} else {
			return nil
		}

		if startPos <= lastPos {
			startPosForRead := startPos
			for pos, e := range entryMap {
				if pos >= startPosForRead {
					result = append(result, e)
					startPosForRead = pos + 1
				} else if pos > startPosForRead && len(entryMap) > 0 {
					break
				}
			}

			// Sort by position
			for i := 0; i < len(result); i++ {
				for j := i + 1; j < len(result); j++ {
					if result[i].Position > result[j].Position {
						result[i], result[j] = result[j], result[i]
					}
				}
			}

			return result
		}
	}

	// If not in cache or startPos beyond our entries, read from lin-kv
	currentPos := startPos

	// First get the max position for this journal from storage
	posKey := fmt.Sprintf("journal:%s:pos", journalName)
	maxPos, err := lkv.ReadInt(ctx, posKey)
	if err != nil || maxPos <= 0 {
		return nil
	}

	// If startPos is beyond what we have locally but exists in storage, we need to fetch from there
	// But lin-kv doesn't support range queries, so we'd need to read each entry

	// For simplicity, if we don't have entries in memory up to startPos, return nil
	if currentPos > maxPos {
		return nil
	}

	// Read entries starting from startPos up to maxPos
	startMax := currentPos
	if startMax > lastPos {
		return nil
	}

	for pos := startMax; pos <= lastPos; pos++ {
		key := fmt.Sprintf("journal:%s:%d", journalName, pos)
		entryVal, err := lkv.ReadInt(ctx, key)
		if err != nil {
			break
		}
		result = append(result, JournalEntry{
			Position: pos,
			Entry:    entryVal,
		})
	}

	return result
}

// AppendRequest is the request to append to a journal or fetch journals
type AppendRequest struct {
